const crypto = require('crypto');

const body = $json.body;
const headers = $json.headers;
const sigHeader = headers['stripe-signature'] ?? '';
const secret = process.env.STRIPE_WEBHOOK_SECRET || 'whsec_YOUR_WEBHOOK_SECRET_HERE';

const rawBody = typeof body === 'string' ? body : JSON.stringify(body);

// Parse stripe-signature header
const sigParts = sigHeader.split(',').reduce((acc, part) => {
  const [k, v] = part.split('=');
  acc[k] = v;
  return acc;
}, {});

const timestamp = sigParts['t'];
const expectedV1 = sigParts['v1'];

if (!timestamp || !expectedV1) {
  return [{ json: { valid: false, reason: 'missing_signature_parts' } }];
}

const signedPayload = timestamp + '.' + rawBody;
const expected = crypto.createHmac('sha256', secret).update(signedPayload).digest('hex');

if (expected !== expectedV1) {
  return [{ json: { valid: false, reason: 'invalid_signature' } }];
}

const eventType = body.type ?? '';
const dataObject = body.data?.object ?? {};

// En checkout.session.completed, el user_id viene en client_reference_id
let userId = dataObject.client_reference_id ?? null;

return [{ json: { valid: true, event_type: eventType, data: dataObject, user_id: userId } }];

const ev = $json;
const data = ev.data;
const eventType = ev.event_type;

// We only process checkout.session.completed for new subs
// and customer.subscription.updated/deleted for updates
let skip = false;
let subStatus = 'active';
let planId = '';
let expiresAt = null;
let providerSubId = '';

if (eventType === 'checkout.session.completed') {
  if (data.payment_status !== 'paid') {
    skip = true;
  }
  providerSubId = data.subscription;
} else if (eventType === 'customer.subscription.updated' || eventType === 'customer.subscription.deleted') {
  subStatus = data.status;
  providerSubId = data.id;
  expiresAt = data.current_period_end ? new Date(data.current_period_end * 1000).toISOString() : null;
} else {
  skip = true;
}

// Map Stripe status to EchoSoul plans
const STATUS_MAP = {
  active:   { plan: 'premium', daily_limit: 9999 },
  trialing: { plan: 'premium', daily_limit: 9999 },
  past_due: { plan: 'premium', daily_limit: 9999 },
  unpaid:   { plan: 'free',    daily_limit: 20 },
  canceled: { plan: 'free',    daily_limit: 20 },
  incomplete: { plan: 'free',    daily_limit: 20 },
  incomplete_expired: { plan: 'free', daily_limit: 20 }
};

const planInfo = STATUS_MAP[subStatus] ?? { plan: 'free', daily_limit: 20 };

return [{ json: {
  skip,
  user_id: ev.user_id,
  provider: 'stripe',
  provider_sub_id: providerSubId,
  status: subStatus,
  plan: planInfo.plan,
  daily_limit: planInfo.daily_limit,
  expires_at: expiresAt,
  plan_id: planId,
  event_type: eventType,
  raw_event: $('Webhook Stripe').first().json.body
}}];
